import{_ as i,a0 as p,w as d,s as r,I as l,x as s,a1 as t,A as n,ao as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"给大家安利一下 PowerShell | LCTT x X-CMD","titleTemplate":false,"description":"给大家安利一下 PowerShell | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"给大家安利一下 PowerShell | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"给大家安利一下 PowerShell | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20180206 Power(Shell) to the people","title":"给大家安利一下 PowerShell","tag":"201903","desc":""},"relativePath":"201903/20180206 Power(Shell) to the people.md","filePath":"[post].md"}'),h={name:"201903/20180206 Power(Shell) to the people.md"};function u(g,e,b,m,k,c){const a=p("Link");return d(),r("div",null,[e[41]||(e[41]=l("h1",{id:"给大家安利一下-powershell",tabindex:"-1"},[s("给大家安利一下 PowerShell "),l("a",{class:"header-anchor",href:"#给大家安利一下-powershell","aria-label":"Permalink to “给大家安利一下 PowerShell”"},"​")],-1)),e[42]||(e[42]=l("blockquote",null,[l("p",null,"代码更简洁、脚本更清晰、跨平台一致性等好处是让 Linux 和 OS X 用户喜爱 PowerShell 的原因。")],-1)),e[43]||(e[43]=l("p",null,[l("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/BUSINESS_lightbulbs.png?itok=pwp22hTw",alt:""})],-1)),l("p",null,[e[4]||(e[4]=s("今年（2018）早些时候，",-1)),t(a,{href:"https://github.com/PowerShell/PowerShell/blob/master/README.md"},{default:n(()=>[...e[0]||(e[0]=[s("Powershell Core",-1)])]),_:1}),e[5]||(e[5]=s(" 以 ",-1)),t(a,{href:"https://spdx.org/licenses/MIT"},{default:n(()=>[...e[1]||(e[1]=[s("MIT",-1)])]),_:1}),e[6]||(e[6]=s(" 开源协议发布了",-1)),t(a,{href:"https://blogs.msdn.microsoft.com/powershell/2018/01/10/powershell-core-6-0-generally-available-ga-and-supported/"},{default:n(()=>[...e[2]||(e[2]=[s("正式可用版（GA）",-1)])]),_:1}),e[7]||(e[7]=s("。PowerShell 算不上是新技术。自 2006 年为 Windows 发布了第一版 PowerShell 以来，PowerShell 的创建者在",-1)),t(a,{href:"http://www.jsnover.com/Docs/MonadManifesto.pdf"},{default:n(()=>[...e[3]||(e[3]=[s("结合了",-1)])]),_:1}),e[8]||(e[8]=s(" Unⅸ shell 的强大和灵活的同时也在弥补他们所意识到的缺点，特别是从组合命令中获取值时所要进行的文本操作。",-1))]),e[44]||(e[44]=o(`<p>在发布了 5 个主要版本之后，PowerShell 已经可以在所有主流操作系统上（包括 OS X 和 Linux）本地运行同样创新的 shell 和命令行环境。一些人（应该说是大多数人）可能依旧在嘲弄这位诞生于 Windows 的闯入者的大胆和冒失：为那些远古以来（从千禧年开始算不算？）便存在着强大的 shell 环境的平台引荐自己。在本帖中，我希望可以将 PowerShell 的优势介绍给大家，甚至是那些经验老道的用户。</p><h3 id="跨平台一致性" tabindex="-1">跨平台一致性 <a class="header-anchor" href="#跨平台一致性" aria-label="Permalink to “跨平台一致性”">​</a></h3><p>如果你计划将脚本从一个执行环境迁移到另一个平台时，你需要确保只使用了那些在两个平台下都起作用的命令和语法。比如在 GNU 系统中，你可以通过以下方式获取昨天的日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>date --date=&quot;1 day ago&quot;</span></span></code></pre></div><p>在 BSD 系统中（比如 OS X），上述语法将没办法工作，因为 BSD 的 date 工具需要以下语法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>date -v -1d</span></span></code></pre></div><p>因为 PowerShell 具有宽松的许可证，并且在所有的平台都有构建，所以你可以把 PowerShell 和你的应用一起打包。因此，当你的脚本运行在目标系统中时，它们会运行在一样的 shell 环境中，使用与你的测试环境中同样的命令实现。</p><h3 id="对象和结构化数据" tabindex="-1">对象和结构化数据 <a class="header-anchor" href="#对象和结构化数据" aria-label="Permalink to “对象和结构化数据”">​</a></h3><p>*nix 命令和工具依赖于你使用和操控非结构化数据的能力。对于那些长期活在 <code>sed</code>、 <code>grep</code> 和 <code>awk</code> 环境下的人们来说，这可能是小菜一碟，但现在有更好的选择。</p><p>让我们使用 PowerShell 重写那个获取昨天日期的实例。为了获取当前日期，使用 <code>Get-Date</code> cmdlet（读作 “commandlet”）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; Get-Date                        </span></span>
<span class="line"><span></span></span>
<span class="line"><span>Sunday, January 21, 2018 8:12:41 PM</span></span></code></pre></div><p>你所看到的输出实际上并不是一个文本字符串。不如说，这是 .Net Core 对象的一个字符串表现形式。就像任何 OOP 环境中的对象一样，它具有类型以及你可以调用的方法。</p><p>让我们来证明这一点：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; $(Get-Date).GetType().FullName</span></span>
<span class="line"><span>System.DateTime</span></span></code></pre></div>`,14)),l("p",null,[e[10]||(e[10]=l("code",null,"$(...)",-1)),e[11]||(e[11]=s(" 语法就像你所期望的 POSIX shell 中那样，计算括弧中的命令然后替换整个表达式。但是在 PowerShell 中，这种表达式中的 ",-1)),e[12]||(e[12]=l("code",null,"$",-1)),e[13]||(e[13]=s(" 是可选的。并且，最重要的是，结果是一个 .Net 对象，而不是文本。因此我们可以调用该对象中的 ",-1)),e[14]||(e[14]=l("code",null,"GetType()",-1)),e[15]||(e[15]=s(" 方法来获取该对象类型（类似于 Java 中的 ",-1)),e[16]||(e[16]=l("code",null,"Class",-1)),e[17]||(e[17]=s(" 对象），",-1)),e[18]||(e[18]=l("code",null,"FullName",-1)),e[19]||(e[19]=s()),t(a,{href:"https://docs.microsoft.com/en-us/dotnet/csharp/programming-guide/classes-and-structs/properties"},{default:n(()=>[...e[9]||(e[9]=[s("属性",-1)])]),_:1}),e[20]||(e[20]=s(" 则用来获取该类型的全称。",-1))]),e[45]||(e[45]=o(`<p>那么，这种对象导向的 shell 是如何让你的工作变得更加简单呢？</p><p>首先，你可将任何对象排进 <code>Get-Member</code> cmdlet 来查看它提供的所有方法和属性。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; (Get-Date) | Get-Member</span></span>
<span class="line"><span>PS /home/yevster/Documents/ArticlesInProgress&gt; $(Get-Date) | Get-Member         </span></span>
<span class="line"><span></span></span>
<span class="line"><span></span></span>
<span class="line"><span>   TypeName: System.DateTime</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name                 MemberType     Definition                                 </span></span>
<span class="line"><span>----                 ----------     ----------                                 </span></span>
<span class="line"><span>Add                  Method         datetime Add(timespan value)               </span></span>
<span class="line"><span>AddDays              Method         datetime AddDays(double value)             </span></span>
<span class="line"><span>AddHours             Method         datetime AddHours(double value)            </span></span>
<span class="line"><span>AddMilliseconds      Method         datetime AddMilliseconds(double value)     </span></span>
<span class="line"><span>AddMinutes           Method         datetime AddMinutes(double value)          </span></span>
<span class="line"><span>AddMonths            Method         datetime AddMonths(int months)             </span></span>
<span class="line"><span>AddSeconds           Method         datetime AddSeconds(double value)          </span></span>
<span class="line"><span>AddTicks             Method         datetime AddTicks(long value)              </span></span>
<span class="line"><span>AddYears             Method         datetime AddYears(int value)               </span></span>
<span class="line"><span>CompareTo            Method         int CompareTo(System.Object value), int ...</span></span></code></pre></div><p>你可以很快的看到 DateTime 对象具有一个 <code>AddDays</code> 方法，从而可以使用它来快速的获取昨天的日期：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; (Get-Date).AddDays(-1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Saturday, January 20, 2018 8:24:42 PM</span></span></code></pre></div><p>为了做一些更刺激的事，让我们调用 Yahoo 的天气服务（因为它不需要 API 令牌）然后获取你的本地天气。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$city=&quot;Boston&quot;</span></span>
<span class="line"><span>$state=&quot;MA&quot;</span></span>
<span class="line"><span>$url=&quot;https://query.yahooapis.com/v1/public/yql?q=select%20*%20from%20weather.forecast%20where%20woeid%20in%20(select%20woeid%20from%20geo.places(1)%20where%20text%3D%22\${city}%2C%20\${state}%22)&amp;format=json&amp;env=store%3A%2F%2Fdatatables.org%2Falltableswithkeys&quot;</span></span></code></pre></div><p>现在，我们可以使用老派的方法然后直接运行 <code>curl $url</code> 来获取 JSON 二进制对象，或者……</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$weather=(Invoke-RestMethod $url)</span></span></code></pre></div><p>如果你查看了 <code>$weather</code> 类型（运行 <code>echo $weather.GetType().FullName</code>），你将会发现它是一个 <code>PSCustomObject</code>。这是一个用来反射 JSON 结构的动态对象。</p><p>然后 PowerShell 可以通过 tab 补齐来帮助你完成命令输入。只需要输入 <code>$weather.</code>（确报包含了 <code>.</code>）然后按下 <code>Tab</code> 键。你将看到所有根级别的 JSON 键。输入其中的一个，然后跟上 <code>.</code> ，再一次按下 <code>Tab</code> 键，你将看到它所有的子键（如果有的话）。</p><p>因此，你可以轻易的导航到你所想要的数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt; echo $weather.query.results.channel.atmosphere.pressure                         </span></span>
<span class="line"><span>1019.0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; echo $weather.query.results.channel.wind.chill                                 41</span></span></code></pre></div><p>并且如果你有非结构化的 JSON 或 CSV 数据（通过外部命令返回的），只需要将它相应的排进 <code>ConverFrom-Json</code> 或 <code>ConvertFrom-CSV</code> cmdlet，然后你可以得到一个漂亮干净的对象。</p><h3 id="计算-vs-自动化" tabindex="-1">计算 vs. 自动化 <a class="header-anchor" href="#计算-vs-自动化" aria-label="Permalink to “计算 vs. 自动化”">​</a></h3><p>我们使用 shell 用于两种目的。一个是用于计算，运行独立的命令然后手动响应它们的输出。另一个是自动化，通过写脚本执行多个命令，然后以编程的方式相应它们的输出。</p><p>我们大多数人都能发现这两种目的在 shell 上的不同且互相冲突的要求。计算任务要求 shell 简洁明了。用户输入的越少越好。但如果用户输入对其他用户来说几乎难以理解，那这一点就不重要了。脚本，从另一个角度来讲是代码。可读性和可维护性是关键。这一方面，POSIX 工具通常是失败的。虽然一些命令通常会为它们的参数提供简洁明了的语法（如：<code>-f</code> 和 <code>--force</code>），但是命令名字本身就不简洁明了。</p><p>PowerShell 提供了几个机制来消除这种浮士德式的平衡。</p><p>首先，tab 补齐可以消除键入参数名的需要。比如：键入 <code>Get-Random -Mi</code>，按下 <code>Tab</code> 然后 PowerShell 将会为你完成参数：<code>Get-Random -Minimum</code>。但是如果你想更简洁一些，你甚至不需要按下 <code>Tab</code>。如下所示，PowerShell 可以理解：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Get-Random -Mi 1 -Ma 10</span></span></code></pre></div><p>因为 <code>Mi</code> 和 <code>Ma</code> 每一个都具有独立不同的补齐。</p><p>你可能已经留意到所有的 PowerShell cmdlet 名称具有动名词结构。这有助于脚本的可读性，但是你可能不想一而再、再而三的键入 <code>Get-</code>。所以并不需要！如果你之间键入了一个名词而没有动词的话，PowerShell 将查找带有该名词的 <code>Get-</code> 命令。</p><blockquote><p>小心：尽管 PowerShell 不区分大小写，但在使用 PowerShell 命令是时，名词首字母大写是一个好习惯。比如，键入 <code>date</code> 将会调用系统中的 <code>date</code> 工具。键入 <code>Date</code> 将会调用 PowerShell 的 <code>Get-Date</code> cmdlet。</p></blockquote><p>如果这还不够，PowerShell 还提供了别名，用来创建简单的名字。比如，如果键入 <code>alias -name cd</code>，你将会发现 <code>cd</code> 在 PowerShell 实际上时 <code>Set-Location</code> 命令的别名。</p><p>所以回顾以下 —— 你可以使用强大的 tab 补全、别名，和名词补全来保持命令名词简洁、自动化和一致性参数名截断，与此同时还可以享受丰富、可读的语法格式。</p><h3 id="那么-你看呢" tabindex="-1">那么……你看呢？ <a class="header-anchor" href="#那么-你看呢" aria-label="Permalink to “那么……你看呢？”">​</a></h3>`,26)),l("p",null,[e[22]||(e[22]=s("这些只是 PowerShell 的一部分优势。还有更多特性和 cmdlet，我还没讨论（如果你想弄哭 ",-1)),e[23]||(e[23]=l("code",null,"grep",-1)),e[24]||(e[24]=s(" 的话，可以查看 ",-1)),t(a,{href:"https://docs.microsoft.com/en-us/powershell/module/microsoft.powershell.core/where-object?view=powershell-6"},{default:n(()=>[...e[21]||(e[21]=[s("Where-Object",-1)])]),_:1}),e[25]||(e[25]=s(" 或其别称 ",-1)),e[26]||(e[26]=l("code",null,"?",-1)),e[27]||(e[27]=s("）。如果你有点怀旧的话，PowerShell 可以为你加载原来的本地工具。但是给自己足够的时间来适应 PowerShell 面向对象 cmdlet 的世界，然后你将发现自己会选择忘记回去的路。",-1))]),e[46]||(e[46]=l("hr",null,null,-1)),l("p",null,[e[29]||(e[29]=s("via: ",-1)),t(a,{href:"https://opensource.com/article/18/2/powershell-people"},{default:n(()=>[...e[28]||(e[28]=[s("https://opensource.com/article/18/2/powershell-people",-1)])]),_:1})]),l("p",null,[e[33]||(e[33]=s("作者：",-1)),t(a,{href:"https://opensource.com/users/yevster"},{default:n(()=>[...e[30]||(e[30]=[s("Yev Bronshteyn",-1)])]),_:1}),e[34]||(e[34]=s(" 译者：",-1)),t(a,{href:"https://github.com/sanfusu"},{default:n(()=>[...e[31]||(e[31]=[s("sanfusu",-1)])]),_:1}),e[35]||(e[35]=s(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[32]||(e[32]=[s("wxy",-1)])]),_:1})]),l("p",null,[e[38]||(e[38]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[36]||(e[36]=[s("LCTT",-1)])]),_:1}),e[39]||(e[39]=s(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:n(()=>[...e[37]||(e[37]=[s("Linux中国",-1)])]),_:1}),e[40]||(e[40]=s(" 荣誉推出",-1))])])}const y=i(h,[["render",u]]);export{S as __pageData,y as default};
